// ====== 贴图路径 / 缓存 / 索引 ======
// 所有原版贴图统一存放在与 index.html 同级的 Textures/ 目录。
// 若需改用 CDN，直接改这里（末尾必须带 /）。
let TEXTURE_ROOT = 'Textures/';
function setTextureRoot(root) { TEXTURE_ROOT = root.endsWith('/') ? root : root + '/'; }

// 把贴图文件名解析为可加载的 URL；已经是完整 URL / blob / data / 已含前缀的路径 时原样返回
function texUrl(name) {
    if (!name) return null;
    if (/^(https?:|blob:|data:|file:|\/\/)/i.test(name)) return name;
    if (name.startsWith(TEXTURE_ROOT)) return name;   // 幂等：避免重复拼接 TEXTURE_ROOT（如撤销时 textureUrl 已是完整路径）
    return TEXTURE_ROOT + name;
}
// 反向：把 URL 还原为贴图文件名（用于存档与命令导出）
function texName(url) {
    if (!url) return null;
    if (url.startsWith(TEXTURE_ROOT)) return url.slice(TEXTURE_ROOT.length);
    return url;
}

// ===== base64(data URI) 贴图 → 云端贴图名 反查 =====
// 部分方块（旧导出/导入循环、自定义上传等）的 textureUrl 是 data:image/png;base64,…
// 而图片内容本身是云端贴图库（Textures/）里的原版贴图。导出时若直接内嵌 base64，
// 命令会变得巨大且不可读（用户强烈反馈「云端材质一直在那里，为什么要内嵌？」）。
// 这里在后台把云端贴图库逐张转成 data URI 建索引（dataURI → 文件名），导出遇到
// base64 贴图时反查出中文名，能查到就输出名字，查不到（真·自定义上传）才回退内嵌。
let _texUriToName = null;          // Map<dataURI, 文件名>
let _texUriMapReady = false;
let _texUriBuildStarted = false;
function ensureTexUriMap() {
    if (_texUriBuildStarted) return;
    _texUriBuildStarted = true;
    _texUriToName = new Map();
    const mkUri = (blob) => new Promise(resolve => {
        const r = new FileReader();
        r.onload = () => resolve(r.result);
        r.onerror = () => resolve(null);
        r.readAsDataURL(blob);
    });
    // 分片并发（每批 24 个），避免一次性 Promise.all(910) 抢占资源；全程后台静默失败
    (async () => {
        try {
            const files = TEX_LIB.map(t => t[0]);
            for (let i = 0; i < files.length; i += 24) {
                const batch = files.slice(i, i + 24);
                await Promise.all(batch.map(async file => {
                    try {
                        const res = await fetch(TEXTURE_ROOT + file);
                        if (!res.ok) return;
                        const blob = await res.blob();
                        const uri = await mkUri(blob);
                        if (uri && uri.startsWith('data:image/png;base64,')) _texUriToName.set(uri, file);
                    } catch (_) {}
                }));
            }
            _texUriMapReady = true;
        } catch (_) { _texUriMapReady = true; }
    })();
}
// 反查 data URI → 云端贴图中文名；查不到返回 null
function texNameFromDataUri(uri) {
    if (!uri || !_texUriToName) return null;
    if (_texUriToName.has(uri)) {
        const file = _texUriToName.get(uri);
        return TEX_NAME_MAP.get(file) || file;
    }
    return null;
}

// 把用户选择的图片文件转成 data URL（base64），使自定义贴图“自包含”：
// 既能随存档 / 命令导出持久保存，也能在重新导入指令时还原。
// （blob: 临时链接做不到——会话结束后失效，重载存档或重新导入都会丢材质）
function fileToDataURL(file) {
    return new Promise((resolve, reject) => {
        const r = new FileReader();
        r.onload = () => resolve(r.result);
        r.onerror = reject;
        r.readAsDataURL(file);
    });
}

// 纹理加载计数：打开大项目（含大量带材质方块）时，所有贴图都是异步 fetch，
// 浏览器并发下载几百上千张图需要时间。这里维护一个全局计数，配合 #projectLoading 遮罩，
// 在“所有纹理就绪”后再隐藏遮罩，避免用户面对空白/卡顿误以为卡死。
//
// ⚠️ 进度分母必须包含「缓存命中」的纹理：loadTextureCached 在缓存命中时同步返回，不走下载。
// 若只把“真正下载”的纹理计入分母，重开已缓存过的项目时分母极小（如只剩 2 张要下），
// 进度就会 0% → 50% → 100% 大跳。正确做法是分母 = 本次会话全部纹理需求（含缓存命中），
// 分子 = 已就绪数（缓存命中即时计入 + 下载完成计入），这样分母通常很大、每完成一张只涨 1/N。
let _pendingDownloads = 0;  // 真正在下载中（未缓存）的纹理数 —— 仅用于“全部完成”判定
let _totalDemand = 0;       // 本次会话纹理需求总数（含缓存命中）—— 进度分母
let _resolvedTex = 0;       // 已就绪的纹理数（缓存命中即时 + 下载完成）—— 进度分子
let _realPct = 0;           // 真实进度%（基于 已就绪/总需求），由计数回调更新
let _displayPct = 0;        // 显示进度%（每帧朝 _realPct 缓动逼近），驱动 DOM
let _progressAnimStart = 0; // 缓动动画起始时间（看门狗用）
let _onAllTexLoaded = null; // 全部下载完时触发的回调

// 仅在「缓存未命中、真正发起下载」时调用：分母 +1、在途 +1
function _incTexPending() {
    _pendingDownloads++;
    _totalDemand++;
    _updateLoadingProgress();
}
// 纹理下载结算（成功 / 失败 / 超时）时调用：在途 -1、已就绪 +1
function _decTexPending() {
    _pendingDownloads = Math.max(0, _pendingDownloads - 1);
    _resolvedTex++;
    _updateLoadingProgress();
    if (_pendingDownloads === 0 && _onAllTexLoaded) {
        const cb = _onAllTexLoaded;
        _onAllTexLoaded = null;
        cb();
    }
}
// 缓存命中（同步返回）时调用：分母 +1、已就绪 +1，进度立即前进
function _countCachedTex() {
    _totalDemand++;
    _resolvedTex++;
    _updateLoadingProgress();
}
function _updateLoadingProgress() {
    // 只更新「真实进度」。DOM 由 _animateProgress 缓动循环统一驱动，避免阶梯跳变。
    _realPct = _totalDemand > 0 ? Math.min(100, _resolvedTex / _totalDemand * 100) : 0;
}
// 缓动显示循环：真实进度（_realPct）受 HTTP/1.1 同域连接槽（默认 6 条）限制，
// 纹理是一批一批完成的（每批 ~6 张几乎同时 onload），直接显示会呈 0→6/N→12/N 阶梯跳变。
// 这里每帧把「显示进度」朝「真实进度」缓动逼近（lerp 0.18），无论底层怎么跳，
// 进度条宽度与百分比数字都连续滑动，彻底消除阶梯感，且一定会收敛到 100%。
async function _animateProgress() {
    const bar = document.getElementById('plProgressBar');
    const pct = document.getElementById('plPercent');
    if (_totalDemand === 0) return;   // 无纹理需求，无需进度动画
    _displayPct = 0;
    _progressAnimStart = Date.now();
    while (true) {
        const diff = _realPct - _displayPct;
        _displayPct = Math.abs(diff) < 0.4 ? _realPct : _displayPct + diff * 0.18;
        const p = Math.min(100, Math.max(0, Math.round(_displayPct)));
        if (bar) bar.style.width = p + '%';
        if (pct) pct.textContent = p + '%';
        // 真实进度到顶且显示已逼近 → 收尾为精确 100%
        if (_realPct >= 100 && _displayPct >= 99.4) {
            if (bar) bar.style.width = '100%';
            if (pct) pct.textContent = '100%';
            break;
        }
        // 绝对看门狗：即便真实进度异常，最多跑 ~25s 也退出，避免空转
        if (Date.now() - _progressAnimStart > 25000) {
            if (bar) bar.style.width = '100%';
            if (pct) pct.textContent = '100%';
            break;
        }
        await new Promise(r => requestAnimationFrame(r));
    }
}
// 等待本次会话所有「真正下载」的纹理完成；若已无在途立即 resolve
function waitForTexturesLoaded() {
    if (_pendingDownloads <= 0) return Promise.resolve();
    return new Promise(resolve => { _onAllTexLoaded = resolve; });
}
// 稳定版等待：纹理可能分批发起（restoreState 之后仍有异步补建块 / 面材质补齐），
// 单次在途归零不代表真的加载完。这里每轮归零后让出一帧复查，确认没有新批次才返回。
// 同时整体受 LOADING_WATCHDOG_MS 总闸约束：即便有纹理因请求挂起而迟迟不结算，也不会无限等待。
async function waitForTexturesStable(maxMs = LOADING_WATCHDOG_MS) {
    const start = Date.now();
    for (let guard = 0; guard < 200; guard++) {
        if (_pendingDownloads > 0) {
            const r = waitForTexturesLoaded();
            const remain = Math.max(0, maxMs - (Date.now() - start));
            const timeout = new Promise(res => setTimeout(res, remain));
            await Promise.race([r, timeout]);
        }
        await new Promise(r => requestAnimationFrame(r));
        if (_pendingDownloads <= 0) return;
        if (Date.now() - start > maxMs) return;
    }
}
// 等两帧，确保浏览器先把“正在加载”遮罩 paint 出来，再跑重负载的 restoreState
function nextFrame() {
    return new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
}
function _sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

// 「重项目」判定阈值：state 里的方块数。超过它就在跑 restoreState 之前先把遮罩画出来。
const HEAVY_PROJECT_BLOCKS = 40;
// 遮罩一旦显示，至少留这么久，避免“闪一下就消失”的突兀感
const LOADING_MIN_VISIBLE_MS = 400;
// 轻项目：restoreState 结束后若纹理仍在下载，先宽限这么久，仍未完成才显示遮罩
const LOADING_GRACE_MS = 180;
// 单张纹理加载的兜底超时：复杂项目几百上千张贴图并发请求时，本地单线程服务器 /
// 浏览器同域连接槽（HTTP/1.1 默认 6 条）可能被占满，个别 <img> 请求会长时间挂起，
// 既不 onload 也不 onerror —— 若只靠回调把 pending 归零，进度就会永远卡在某百分比、
// 遮罩永不消失。这里给每张纹理一个超时，到点强制结算，保证计数一定能归零。
const TEX_LOAD_TIMEOUT_MS = 12000;
// 整个“正在加载”遮罩的最长等待：即便有纹理超时兜底，也再设一道总闸，杜绝任何极端情况下卡死。
const LOADING_WATCHDOG_MS = 20000;

// 统一的「打开/新建项目」加载流程。
// ⚠️ 关键：不能用「setTimeout 延迟 180ms 显示遮罩」——restoreState 是同步重负载，
// 会把主线程占满，定时器回调只能排队等它跑完，结果最需要提示的阻塞期完全没提示，
// 反而在加载都快结束时遮罩才「闪」出来（用户报告的「开复杂项目立即触发加载提示」）。
// 正确做法：用项目规模（方块数）在 task 之前同步决定是否显示遮罩，并确保 paint 后再跑重负载。
async function runProjectOpenLoad(task, opts = {}) {
    _totalDemand = 0; _resolvedTex = 0; _pendingDownloads = 0; _onAllTexLoaded = null;
    const loadingEl = document.getElementById('projectLoading');
    const textEl = document.getElementById('plText');
    const bar = document.getElementById('plProgressBar');
    const pct = document.getElementById('plPercent');
    let shownAt = 0;

    const showMask = (msg) => {
        if (shownAt || !loadingEl) return;
        if (bar) bar.style.width = '0%';
        if (pct) pct.textContent = '0%';
        if (textEl && msg) textEl.textContent = msg;
        loadingEl.style.display = 'flex';
        shownAt = Date.now();
    };
    const setMaskText = (msg) => { if (shownAt && textEl && msg) textEl.textContent = msg; };

    const heavy = (opts.blockCount || 0) >= HEAVY_PROJECT_BLOCKS;
    if (heavy) {
        // 重项目：立刻显示遮罩，并等两帧确保浏览器真的把它画上屏，再去跑阻塞主线程的 restoreState
        showMask('正在构建模型…');
        await nextFrame();
    }

    try { await task(); } catch (e) { console.error('项目加载失败', e); }
    _updateLoadingProgress();  // restoreState 已发起全部纹理请求，刷新真实进度

    // 纹理阶段：restoreState 已同步发起全部贴图请求，此刻才知道真实待下载量
    let animPromise = null;
    if (_totalDemand > 0) {
        // 启动独立的缓动显示循环：每帧把显示进度朝真实进度逼近，与“等待下载完成”并行，
        // 这样进度条/百分比数字是连续滑动的，而非随每批纹理完成而阶梯跳变。
        animPromise = _animateProgress();
        if (_pendingDownloads > 0) {
            if (shownAt) {
                setMaskText('正在加载材质…');
            } else {
                // 轻项目：给一个宽限期，纹理很快下完就完全不显示遮罩（不闪）
                await _sleep(LOADING_GRACE_MS);
                if (_pendingDownloads > 0) showMask('正在加载材质…');
            }
        } else if (shownAt) {
            setMaskText('正在加载材质…');
        }
    }

    const waits = [waitForTexturesStable()];
    if (animPromise) waits.push(animPromise);
    await Promise.all(waits);

    if (shownAt && loadingEl) {
        const rest = LOADING_MIN_VISIBLE_MS - (Date.now() - shownAt);
        if (rest > 0) await _sleep(rest);
        loadingEl.style.display = 'none';
        if (textEl) textEl.textContent = '正在加载项目…';
    }
    // 首启新手教程：场景就绪后，若从未做过/跳过教程则自动弹出章节目录（不打扰已学用户）
    try { if (typeof maybeStartTutorial === 'function') maybeStartTutorial(); } catch (e) {}
}
// 从序列化 state 字符串里低成本估算方块数（每个方块必带 "faceTextures":），
// 避免为了判断规模而多做一次几百 KB 的 JSON.parse。
function estimateStateBlockCount(stateStr) {
    if (!stateStr || typeof stateStr !== 'string') return 0;
    let n = 0, i = 0;
    const key = '"faceTextures":';
    while ((i = stateStr.indexOf(key, i)) !== -1) { n++; i += key.length; }
    return n;
}

// 纹理缓存：同一张图在多个方块 / 多个面之间复用，避免重复下载与解码
const _texCache = new Map();
function loadTextureCached(url, onReady) {
    if (!url) return null;
    const hit = _texCache.get(url);
    if (hit) {
        _countCachedTex();   // 缓存命中：立即计入进度（分母 + 已就绪）
        if (onReady) { if (hit.image && hit.image.width) onReady(hit); else hit.__cbs.push(onReady); }
        return hit;
    }
    _incTexPending();
    // 单张纹理结算：成功 / 失败 / 超时 三者取最先发生者，保证计数必定归零，
    // 避免个别请求挂起导致“正在加载”遮罩卡在某一百分比永不消失。
    let _settled = false;
    const settle = () => {
        if (_settled) return;
        _settled = true;
        if (tex.__decTimer) { clearTimeout(tex.__decTimer); tex.__decTimer = null; }
        _decTexPending();
    };
    const tex = new THREE.TextureLoader().load(url,
        t => { (t.__cbs || []).forEach(cb => cb(t)); t.__cbs = []; settle(); },
        undefined,
        err => { console.warn('纹理加载失败:', url, err); settle(); });
    tex.__cbs = onReady ? [onReady] : [];
    tex.anisotropy = 16;
    // MC 像素风：放大用最近邻保持像素锐利；缩小走 mipmap 的最近邻，远处也不糊成一片
    tex.magFilter = THREE.NearestFilter;
    tex.minFilter = THREE.NearestMipmapLinearFilter;
    tex.generateMipmaps = true;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    // 兜底超时：到点仍未结算（请求挂起）则强制结算，使进度条能走到 100%、遮罩能消失
    tex.__decTimer = setTimeout(() => {
        if (!_settled) console.warn('纹理加载超时（疑似服务端连接受限），强制结算:', url);
        settle();
    }, TEX_LOAD_TIMEOUT_MS);
    _texCache.set(url, tex);
    return tex;
}

// 六个面的中文名与索引（与 CUBE_FACES 顺序一致）
// 0=底(Y-) 1=顶(Y+) 2=左(X-) 3=右(X+) 4=前(Z-) 5=后(Z+)
const FACE_INFO = [
    { i: 0, key: 'bottom', n: '底面', ax: 'Y-' },
    { i: 1, key: 'top',    n: '顶面', ax: 'Y+' },
    { i: 2, key: 'west',   n: '左面', ax: 'X-' },
    { i: 3, key: 'east',   n: '右面', ax: 'X+' },
    { i: 4, key: 'north',  n: '前面', ax: 'Z-' },
    { i: 5, key: 'south',  n: '后面', ax: 'Z+' }
];

// 索引表：文件名 -> 中文名 / 分类；预设 key -> 预设条目
const TEX_NAME_MAP = new Map(TEX_LIB.map(t => [t[0], t[1]]));
const TEX_CAT_MAP  = new Map(TEX_LIB.map(t => [t[0], t[2]]));
const TEX_PRESET_MAP = new Map(TEX_BLOCK_PRESETS.map(p => [p[0], { key: p[0], name: p[1], cat: p[2], faces: p[3] }]));
// 中文名 -> 预设（导入命令时按中文名反查）
const TEX_PRESET_BY_NAME = new Map(TEX_BLOCK_PRESETS.map(p => [p[1], TEX_PRESET_MAP.get(p[0])]));
const TEX_BY_NAME = new Map(TEX_LIB.map(t => [t[1], t[0]]));

function blockPresetName(key) { const p = TEX_PRESET_MAP.get(key); return p ? p.name : null; }
// 贴图文件名 -> 展示用中文名
function texDisplayName(file) { return TEX_NAME_MAP.get(file) || (file || '').replace(/\.(png|jpg)$/i, ''); }

// 读贴图像素，判断透明类型：
//   cutout = 含完全透明(硬镂空，用 alphaTest 丢弃) —— 如树叶/脚手架/堆肥桶/炼药锅
//   semi   = 含半透明(抗锯齿/渐变，用混合)         —— 如玻璃(也走 isGlass 分支)
// 注意：file:// 直接打开会因跨源污染无法读像素(getImageData 抛错)，
// 此时保守返回不透明——请务必用本地服务器(http)打开以正确识别透明。
function detectAlphaMode(img) {
    if (!img || !img.width) return { cutout: false, semi: false };
    try {
        const S = 64;
        const cv = document.createElement('canvas');
        cv.width = cv.height = S;
        const ctx = cv.getContext('2d');
        ctx.drawImage(img, 0, 0, S, S);
        const d = ctx.getImageData(0, 0, S, S).data;
        let cut = false, semi = false;
        for (let i = 3; i < d.length; i += 4) {
            const a = d[i];
            if (a <= 8) cut = true;          // 完全/几乎透明 → 硬镂空
            else if (a < 248) semi = true;   // 半透明(抗锯齿/渐变)
        }
        return { cutout: cut, semi: semi };
    } catch (e) {
        return { cutout: false, semi: false };
    }
}

// 依据贴图透明类型设置材质：
//   玻璃(按文件名 isGlass) → 半透明混合 + 双面
//   硬镂空(cutout)         → alphaTest + transparent(→ updateMaterialSide 自动双面，内壁可见)
//   半透明(semi)           → 混合 + 关 depthWrite
function matApplyTexAlpha(mat, tex, isGlass) {
    if (isGlass) { mat.transparent = true; mat.side = THREE.DoubleSide; mat.needsUpdate = true; return; }
    const mode = detectAlphaMode(tex && tex.image);
    if (mode.cutout) {
        // 硬镂空（草/树叶/花）：走不透明队列 + alphaTest，边缘是硬的像素边界（跟 MC 一致），
        // 也避免透明排序导致的穿插与脏边
        mat.alphaTest = 0.5;
        mat.transparent = false;
        mat.depthWrite = true;
        mat.side = THREE.DoubleSide;
    } else if (mode.semi) {
        mat.transparent = true;
        mat.depthWrite = false;
        mat.side = THREE.DoubleSide;
    }
    mat.needsUpdate = true;
}
